mapper.select:
select id, batch_id, user_id, status, retry_count, error_message, created_at, updated_at
from coupon_claim_task
where batch_id = #{batchId}
  and user_id = #{userId}
limit 1

mapper.update:
update coupon_claim_task
set status = #{status},
    retry_count = case when #{status} = 'FAILED' then retry_count + 1 else retry_count end,
    error_message = #{errorMessage}
where id = #{id}
